import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { orbit, depthRotate, dissolveMorph, displacementTransition, parallaxScroll, magneticCursor, particleEmerge, flyThrough, kineticText } from '@/primitives';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<{name:string,params:any,trigger?:string}>} [cinematicPrimitives]
 * @property {any} [textContent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} THREE - bundled three namespace
 * @property {{loadTexture(url:string):Promise<any>}} textureLoader
 * @property {{loadGLB(url:string):Promise<any>}} glbLoader
 * @property {{loadVideo?(url:string):Promise<any>}} videoLoader
 * @property {{createText(content:string, opts?:any):any}} fontAtlas
 * @property {Record<string,Function>} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * Create the quote‑panel node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container – the adapter will apply position/rotation/scale.
  const root = new Group();

  // ---- Plane geometry & material -------------------------------------------------
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial();

  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously; will be applied when ready.
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // ---- Apply cinematic primitives -------------------------------------------------
  const primitiveHandles = [];

  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const handle = fn(root, prim.params || {});
        primitiveHandles.push(handle);
      }
    }
  }

  // ---- Interaction handlers -------------------------------------------------------
  const timelines = [];
  const originalY = plane.position.y;

  /** @type {Function} */
  function onHover() {
    // rise‑in effect – subtle lift of 0.15 units
    const tl = gsap.to(plane.position, {
      y: originalY + 0.15,
      duration: 0.15,
      ease: 'power3.out',
    });
    timelines.push(tl);
  }

  /** @type {Function} */
  function onClick() {
    ctx.emit('hub-pricing.select', {});
  }

  root.userData.handlers = {
    hover: onHover,
    click: onClick,
  };

  // ---- Cleanup --------------------------------------------------------------------
  root.userData.cleanup = () => {
    // Kill any GSAP timelines we started
    timelines.forEach((t) => t.kill());

    // Dispose material & texture
    if (material.map && material.map.dispose) material.map.dispose();
    if (material.dispose) material.dispose();

    // Dispose geometry
    if (geometry.dispose) geometry.dispose();

    // Cleanup primitives
    primitiveHandles.forEach((h) => {
      if (h && typeof h.cleanup === 'function') {
        h.cleanup();
      }
    });
  };

  // ---- Text (none in this spec, but placeholder for completeness) ---------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize,
      color: item.role?.color || '#e8ecf2',
      align: 'left',
    });
    root.add(txt);
  }

  return root;
}
